+        sb.append("task_type=").append(taskType);
+        if (dimensions != null) {
+            sb.append(", dimensions=").append(dimensions);
+        }
+        if (similarity != null) {
+            sb.append(", similarity=").append(similarity);
+        }
+        if (elementType != null) {
+            sb.append(", element_type=").append(elementType);
+        }
+        return sb.toString();
